import com.kingdomsclaims.ProductionText;
public class ProductionTextTest {
    static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
    public static void main(String[] args){check(ProductionText.quantity(1).equals("0.5"),"half iron cannot display as zero");check(ProductionText.quantity(25).equals("12.5"),"odd section totals retain half iron");check(ProductionText.rate(24,360).equals("+12 every 6 minutes"),"plain six-minute production label");check(ProductionText.rate(24,300).equals("+12 every 5 minutes"),"tax income keeps five-minute interval");check(ProductionText.building("mine",25,true).equals("Mine: 12.5 iron / 6 min"),"mine sections are not mistaken for whole iron");check(ProductionText.building("house",4,true).equals("House: 4 beds"),"housing has named capacity units");check(ProductionText.building("lumber camp",5,false).equals("Woodcutter - Paused"),"paused buildings do not promise output");check(ProductionText.time(181).equals("3:01")&&ProductionText.count(12345).equals("12,345"),"readable timers and exact stored counts");System.out.println("Production display quantity, fractional iron, interval and capacity label regressions passed.");}
}
